INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass kleine Prozessänderungen immer sofort Ergebnisse liefern. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Wirkung braucht oft Zeit"}, {"text": "Ja", "correct": false, "because": "Ergebnisse sind nicht garantiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich einen IT-Prozess optimiere?', 3, '[{"text": "Datenanalyse", "correct": true, "because": "Identifiziert Schwachstellen"}, {"text": "Schnelle Umsetzung", "correct": false, "because": "Qualität zählt mehr"}, {"text": "Neue Hardware", "correct": false, "because": "Nicht immer nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte fördern eine nachhaltige Prozessverbesserung?', 5, '[{"text": "Regelmäßiges Feedback", "correct": true, "because": "Liefert Optimierungsideen"}, {"text": "Team-Einbindung", "correct": true, "because": "Fördert Akzeptanz"}, {"text": "Höhere Bandbreite", "correct": false, "because": "Technisch irrelevant"}, {"text": "Weniger Dokumentation", "correct": false, "because": "Behindert Nachvollziehbarkeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Prozessoptimierung reduziert Fehler. b) Sie erhöht immer die Kosten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kosten können sinken"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich Netzwerkprozesse verbessere?', 4, '[{"text": "Datenflussanalyse", "correct": false, "because": "Zeigt Engpässe"}, {"text": "Nutzerrückmeldungen", "correct": false, "because": "Liefert Praxiswissen"}, {"text": "Bürogestaltung", "correct": true, "because": "Irrelevant für Netzwerk"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Verbesserungen immer neue Software brauchen?', 2, '[{"text": "Nein", "correct": true, "because": "Prozesse können ohne optimiert werden"}, {"text": "Ja", "correct": false, "because": "Software ist nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich, wenn ich Backup-Prozesse anpasse?', 3, '[{"text": "Höhere Zuverlässigkeit", "correct": true, "because": "Sichert Datenverfügbarkeit"}, {"text": "Schnellere Hardware", "correct": false, "because": "Nicht primär"}, {"text": "Weniger Teamarbeit", "correct": false, "because": "Kein Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen Prozessoptimierung effektiv?', 5, '[{"text": "Klar definierte Ziele", "correct": true, "because": "Gibt Richtung vor"}, {"text": "Regelmäßige Überprüfung", "correct": true, "because": "Passt Prozesse an"}, {"text": "Mehr Server", "correct": false, "because": "Nicht zentral"}, {"text": "Schnelle Ergebnisse", "correct": false, "because": "Langfristigkeit zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Optimierung spart Zeit. b) Sie erfordert immer externe Berater. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Interne Teams reichen oft"}, {"text": "Beides stimmt", "correct": "false", "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": "false", "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": "false", "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um einen Patch-Prozess zu verbessern?', 4, '[{"text": "Testumgebung", "correct": false, "because": "Sichert Stabilität"}, {"text": "Priorisierung", "correct": false, "because": "Fokussiert kritische Updates"}, {"text": "Neues Branding", "correct": true, "because": "Irrelevant für Prozess"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind kleine Änderungen immer risikofrei?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Änderungen können Fehler verursachen"}, {"text": "Ja", "correct": false, "because": "Risiken bleiben"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bringt eine Optimierung der Ticket-Bearbeitung?', 4, '[{"text": "Schnellere Lösung", "correct": true, "because": "Verbessert Support"}, {"text": "Höhere Kundenzufriedenheit", "correct": true, "because": "Effizienz steigt"}, {"text": "Neue Hardware", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Prozessoptimierung nur für große Firmen ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Teams profitieren"}, {"text": "Ja", "correct": false, "because": "Skalierung ist egal"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist entscheidend, wenn ich Software-Updates effizienter gestalte?', 3, '[{"text": "Automatisierung", "correct": true, "because": "Reduziert manuellen Aufwand"}, {"text": "Schnelle CPUs", "correct": false, "because": "Sekundär"}, {"text": "Bunte Interfaces", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Optimierung braucht Teamarbeit. b) Sie ersetzt neue Hardware.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Hardware ist oft ergänzend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte berücksichtige ich bei der Verbesserung eines Monitoring-Systems?', 5, '[{"text": "Echtzeit-Daten", "correct": true, "because": "Schnelle Reaktion möglich"}, {"text": "Benachrichtigungen", "correct": true, "because": "Warnt bei Problemen"}, {"text": "Schickes Design", "correct": false, "because": "Ästhetik sekundär"}, {"text": "Manuelle Prüfung", "correct": false, "because": "Zu langsam"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist unwichtig, wenn ich den Support-Prozess verbessere?', 3, '[{"text": "Reaktionszeit", "correct": false, "because": "Entscheidend für Nutzer"}, {"text": "Feedbackschleifen", "correct": false, "because": "Fördert Lernen"}, {"text": "Kaffeemaschine", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Erhöht Optimierung immer die Komplexität?', 3, '[{"text": "Nein", "correct": true, "because": "Kann Prozesse vereinfachen"}, {"text": "Ja", "correct": false, "because": "Ziel ist Effizienz"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Verbesserungen immer teuer sind?', 2, '[{"text": "Nein", "correct": true, "because": "Kleine Änderungen sind oft günstig"}, {"text": "Ja", "correct": false, "because": "Kosten variieren"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist entscheidend, wenn ich Deployment-Prozesse verbessere?', 4, '[{"text": "Automatisierte Tests", "correct": true, "because": "Sichert Stabilität"}, {"text": "Schnellere Server", "correct": false, "because": "Nicht primär"}, {"text": "Neues Logo", "correct": false, "because": "Irrelevant"}]');
